BEGIN;
ALTER TABLE "User" ADD COLUMN "active" BOOLEAN NOT NULL DEFAULT true;
ALTER TABLE "Flyer" ADD COLUMN "archivedAt" TIMESTAMP(3);
ALTER TABLE "Invoice" ADD COLUMN "state" TEXT NOT NULL DEFAULT 'issued', ADD COLUMN "pricingMode" TEXT NOT NULL DEFAULT 'manual', ADD COLUMN "pricingFingerprint" TEXT, ADD COLUMN "needsReview" BOOLEAN NOT NULL DEFAULT false;
ALTER TABLE "Shipment" ADD COLUMN "paymentTerms" TEXT NOT NULL DEFAULT 'invoice', ADD COLUMN "freeOfCharge" BOOLEAN NOT NULL DEFAULT false, ADD COLUMN "exception" TEXT, ADD COLUMN "exceptionReason" TEXT NOT NULL DEFAULT '', ADD COLUMN "exceptionAt" TIMESTAMP(3), ADD COLUMN "deliveryMode" TEXT NOT NULL DEFAULT 'courier', ADD COLUMN "deliveryBookedAt" TIMESTAMP(3), ADD COLUMN "dispatchedAt" TIMESTAMP(3), ADD COLUMN "handedOverAt" TIMESTAMP(3);
UPDATE "Shipment" s SET "paymentTerms" = CASE WHEN s."payStatus"='cod' THEN 'cod' WHEN s."payStatus"='monthly' OR p."terms"='monthly' THEN 'monthly' ELSE 'invoice' END FROM "Supplier" p WHERE s."supplierId"=p.id;
UPDATE "Shipment" SET "deliveryMode"='pickup' WHERE "lastMileCourier"='Hub pickup';
UPDATE "Shipment" SET "deliveryBookedAt"="createdAt" WHERE "lastMileRef" IS NOT NULL;
UPDATE "Shipment" SET "handedOverAt"="createdAt" WHERE "status"='delivered';
ALTER TABLE "ShipmentLog" ADD COLUMN "actorId" TEXT;
DROP INDEX "Receipt_shipmentId_key";
CREATE INDEX "Receipt_shipmentId_uploadedAt_idx" ON "Receipt"("shipmentId","uploadedAt");
CREATE UNIQUE INDEX "Receipt_one_pending_per_shipment" ON "Receipt"("shipmentId") WHERE "status"='pending';
ALTER TABLE "Receipt" ADD COLUMN "reviewedAt" TIMESTAMP(3), ADD COLUMN "reviewedById" TEXT, ADD COLUMN "reviewedByName" TEXT, ADD COLUMN "reviewReason" TEXT NOT NULL DEFAULT '';
ALTER TABLE "StatementReceipt" ADD COLUMN "reviewedAt" TIMESTAMP(3), ADD COLUMN "reviewedById" TEXT, ADD COLUMN "reviewedByName" TEXT, ADD COLUMN "reviewReason" TEXT NOT NULL DEFAULT '';
UPDATE "Receipt" SET "reviewReason"='Payment could not be verified. Please contact support with your transaction reference.' WHERE status='rejected';
UPDATE "StatementReceipt" SET "reviewReason"='Payment could not be verified. Please contact support with your transaction reference.' WHERE status='rejected';
ALTER TABLE "Todo" ADD COLUMN "receiptId" TEXT, ADD COLUMN "statementReceiptId" TEXT;
CREATE UNIQUE INDEX "Todo_receiptId_key" ON "Todo"("receiptId");
CREATE UNIQUE INDEX "Todo_statementReceiptId_key" ON "Todo"("statementReceiptId");
UPDATE "Todo" SET done=true WHERE auto=true AND text LIKE 'Review % receipt — %';
INSERT INTO "Todo" (id,role,text,auto,done,"createdAt","receiptId") SELECT 'receipt_task_'||r.id,'admin','Review '||r.method||' receipt — '||s.code,true,false,r."uploadedAt",r.id FROM "Receipt" r JOIN "Shipment" s ON s.id=r."shipmentId" WHERE r.status='pending';
CREATE TABLE "ShipmentCost" (id TEXT PRIMARY KEY,"shipmentId" TEXT NOT NULL,name TEXT NOT NULL,category "ExpenseCategory" NOT NULL,amount DECIMAL(12,2) NOT NULL,"sourceCurrency" "Currency" NOT NULL DEFAULT 'BDT',"sourceAmount" DECIMAL(14,2),"sourceFxRate" DECIMAL(12,6) NOT NULL DEFAULT 1,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"voidedAt" TIMESTAMP(3),"voidReason" TEXT NOT NULL DEFAULT '',CONSTRAINT "ShipmentCost_shipmentId_fkey" FOREIGN KEY("shipmentId") REFERENCES "Shipment"(id) ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE INDEX "ShipmentCost_shipmentId_idx" ON "ShipmentCost"("shipmentId");
ALTER TABLE "Expense" ADD COLUMN "costId" TEXT, ADD COLUMN "reversalOfId" TEXT, ADD COLUMN "reversedAt" TIMESTAMP(3);
CREATE UNIQUE INDEX "Expense_reversalOfId_key" ON "Expense"("reversalOfId");
ALTER TABLE "Expense" ADD CONSTRAINT "Expense_costId_fkey" FOREIGN KEY("costId") REFERENCES "ShipmentCost"(id) ON DELETE RESTRICT ON UPDATE CASCADE;
INSERT INTO "ShipmentCost" (id,"shipmentId",name,category,amount,"sourceCurrency","sourceAmount","sourceFxRate","createdAt") SELECT 'cost_'||id,"shipmentId",reason,category,amount,"sourceCurrency","sourceAmount","sourceFxRate","createdAt" FROM "Expense" WHERE "shipmentId" IS NOT NULL AND "costField" IS NULL;
UPDATE "Expense" SET "costId"='cost_'||id WHERE "shipmentId" IS NOT NULL AND "costField" IS NULL;
ALTER TABLE "Payment" ADD COLUMN "receiptId" TEXT, ADD COLUMN "statementReceiptId" TEXT, ADD COLUMN "supplierId" TEXT, ADD COLUMN "flyerId" TEXT, ADD COLUMN "reversalOfId" TEXT, ADD COLUMN "reversedAt" TIMESTAMP(3);
CREATE UNIQUE INDEX "Payment_reversalOfId_key" ON "Payment"("reversalOfId");
ALTER TABLE "Payment" ADD CONSTRAINT "Payment_receiptId_fkey" FOREIGN KEY("receiptId") REFERENCES "Receipt"(id) ON DELETE RESTRICT ON UPDATE CASCADE, ADD CONSTRAINT "Payment_statementReceiptId_fkey" FOREIGN KEY("statementReceiptId") REFERENCES "StatementReceipt"(id) ON DELETE RESTRICT ON UPDATE CASCADE;
UPDATE "Payment" p SET "supplierId"=s."supplierId" FROM "Shipment" s WHERE p."shipmentId"=s.id;
UPDATE "Payment" p SET "supplierId"=s.id FROM "Supplier" s WHERE p.kind='customer-credit' AND p.reference=s.code||' advance';
UPDATE "Payment" p SET "receiptId"=r.id FROM "Receipt" r JOIN "Shipment" s ON s.id=r."shipmentId" WHERE r.status='approved' AND p."shipmentId"=s.id AND p.method=r.method AND p.reference=s.code||' / '||r."txnRef";
UPDATE "Payment" p SET "statementReceiptId"=r.id FROM "StatementReceipt" r JOIN "StatementLink" l ON l.id=r."linkId" JOIN "Shipment" s ON s."supplierId"=l."supplierId" WHERE r.status='approved' AND p."receiptId" IS NULL AND p."shipmentId"=s.id AND p.method=r.method AND p.reference=s.code||' / '||r."txnRef";
UPDATE "Payment" p SET "flyerId"=f.id FROM "Flyer" f JOIN "FlightFlyer" m ON m."flyerId"=f.id JOIN "Flight" x ON x.id=m."flightId" WHERE p.kind='flyer' AND p."flightId"=x.id AND p.reference=x.code||' flyer '||f.name;
ALTER TABLE "FundTransfer" ADD COLUMN "reversalOfId" TEXT, ADD COLUMN "reversedAt" TIMESTAMP(3);
ALTER TABLE "CustomerRefund" ADD COLUMN "reversalOfId" TEXT, ADD COLUMN "reversedAt" TIMESTAMP(3);
CREATE UNIQUE INDEX "FundTransfer_reversalOfId_key" ON "FundTransfer"("reversalOfId");
CREATE UNIQUE INDEX "CustomerRefund_reversalOfId_key" ON "CustomerRefund"("reversalOfId");
CREATE TABLE "LedgerReversal" (id TEXT PRIMARY KEY,kind TEXT NOT NULL,"recordId" TEXT NOT NULL,reason TEXT NOT NULL,"actorId" TEXT NOT NULL,"actorName" TEXT NOT NULL,"offsetId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX "LedgerReversal_kind_recordId_key" ON "LedgerReversal"(kind,"recordId");
CREATE TABLE "AuditEvent" (id TEXT PRIMARY KEY,"actorId" TEXT NOT NULL,"actorName" TEXT NOT NULL,action TEXT NOT NULL,entity TEXT NOT NULL,details JSONB NOT NULL,before JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "AuditEvent_createdAt_idx" ON "AuditEvent"("createdAt");
COMMIT;
